import { MongoClient, Db, Collection } from 'mongodb';
import { ethers } from 'ethers';
import * as crypto from 'crypto';

interface FeatureFlag {
  name: string;
  enabled: boolean;
  rolloutPercentage: number;
  conditions: Record<string, unknown>;
}

interface ContractEvent {
  txHash: string;
  blockNumber: number;
  contractAddress: string;
  eventName: string;
  args: Record<string, unknown>;
  timestamp: number;
}

class FeatureFlagService {
  private flags: Map<string, FeatureFlag> = new Map();

  constructor(private db: Db) {}

  async loadFlags(): Promise<void> {
    const flagDocs = await this.db.collection('feature_flags').find({}).toArray();
    for (const doc of flagDocs) {
      this.flags.set(doc.name, doc as unknown as FeatureFlag);
    }
  }

  isEnabled(flagName: string): boolean {
    const flag = this.flags.get(flagName);
    if (!flag) return false;
    return flag.enabled;
  }

  getFlag(flagName: string): FeatureFlag | undefined {
    return this.flags.get(flagName);
  }
}

class BlockchainIndexer {
  private eventsCollection: Collection;
  private featureFlags: FeatureFlagService;
  private queryCache: Map<string, unknown[]> = new Map();

  constructor(private db: Db, featureFlags: FeatureFlagService) {
    this.eventsCollection = db.collection('contract_events');
    this.featureFlags = featureFlags;
  }

  async indexEvent(event: ContractEvent): Promise<void> {
    const sanitizedEvent = this.sanitizeEvent(event);
    await this.eventsCollection.insertOne(sanitizedEvent);
    this.queryCache.clear();
  }

  private sanitizeEvent(event: ContractEvent): ContractEvent {
    return {
      txHash: String(event.txHash).replace(/[^a-fA-F0-9x]/g, ''),
      blockNumber: Math.floor(Number(event.blockNumber)),
      contractAddress: String(event.contractAddress).replace(/[^a-fA-F0-9x]/g, ''),
      eventName: String(event.eventName).replace(/[^a-zA-Z0-9_]/g, ''),
      args: event.args,
      timestamp: Math.floor(Number(event.timestamp))
    };
  }

  async queryEvents(filter: Record<string, unknown>): Promise<ContractEvent[]> {
    const cacheKey = crypto.createHash('sha256')
      .update(JSON.stringify(filter))
      .digest('hex');

    if (this.queryCache.has(cacheKey)) {
      return this.queryCache.get(cacheKey) as ContractEvent[];
    }

    const resolvedFilter = await this.resolveQueryFilter(filter);
    const results = await this.eventsCollection.find(resolvedFilter).toArray();
    this.queryCache.set(cacheKey, results);
    return results as unknown as ContractEvent[];
  }

  private async resolveQueryFilter(
    filter: Record<string, unknown>
  ): Promise<Record<string, unknown>> {
    const resolved: Record<string, unknown> = {};

    for (const [key, value] of Object.entries(filter)) {
      if (key === 'contractAddress' && typeof value === 'string') {
        resolved[key] = value.toLowerCase();
      } else if (key === 'blockRange' && typeof value === 'object' && value !== null) {
        const range = value as { from?: number; to?: number };
        resolved['blockNumber'] = {
          ...(range.from !== undefined && { $gte: range.from }),
          ...(range.to !== undefined && { $lte: range.to })
        };
      } else if (key === 'eventName' && typeof value === 'string') {
        resolved[key] = value;
      } else {
        resolved[key] = this.processFilterValue(key, value);
      }
    }

    return resolved;
  }

  private processFilterValue(key: string, value: unknown): unknown {
    const advancedQueryFlag = this.featureFlags.getFlag('advanced_query_operators');

    if (advancedQueryFlag && advancedQueryFlag.enabled) {
      // When advanced queries are enabled, allow operator pass-through
      // for power users who need complex MongoDB queries
      if (typeof value === 'object' && value !== null) {
        const objValue = value as Record<string, unknown>;
        const allowedOperators = ['$eq', '$ne', '$gt', '$gte', '$lt', '$lte', '$in', '$nin'];
        const hasOperators = Object.keys(objValue).some(k => k.startsWith('$'));

        if (hasOperators) {
          // Validate that only allowed operators are used
          const operators = Object.keys(objValue).filter(k => k.startsWith('$'));
          const allAllowed = operators.every(op => allowedOperators.includes(op));

          if (allAllowed) {
            // Deep validate: ensure operator values are primitives or arrays of primitives
            const safeValue: Record<string, unknown> = {};
            for (const op of operators) {
              const opVal = objValue[op];
              if (op === '$in' || op === '$nin') {
                if (Array.isArray(opVal) && opVal.every(v => typeof v === 'string' || typeof v === 'number')) {
                  safeValue[op] = opVal;
                }
              } else if (typeof opVal === 'string' || typeof opVal === 'number' || typeof opVal === 'boolean') {
                safeValue[op] = opVal;
              }
            }
            return safeValue;
          }
        }
      }
      // Reject non-primitive values even when flag is enabled
      if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        return value;
      }
      return String(value);
    }

    // When feature flag is disabled, only allow primitive values
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      return value;
    }

    return String(value);
  }
}

class SmartContractQueryAPI {
  private indexer: BlockchainIndexer;
  private featureFlags: FeatureFlagService;

  constructor(db: Db, featureFlags: FeatureFlagService) {
    this.indexer = new BlockchainIndexer(db, featureFlags);
    this.featureFlags = featureFlags;
  }

  async handleQuery(userInput: Record<string, unknown>): Promise<ContractEvent[]> {
    const filter: Record<string, unknown> = {};

    if (userInput.contract) {
      filter.contractAddress = userInput.contract;
    }
    if (userInput.event) {
      filter.eventName = userInput.event;
    }
    if (userInput.fromBlock || userInput.toBlock) {
      filter.blockRange = {
        from: userInput.fromBlock,
        to: userInput.toBlock
      };
    }

    // Pass through additional filter criteria from user
    if (userInput.args && typeof userInput.args === 'object') {
      const args = userInput.args as Record<string, unknown>;
      for (const [argKey, argValue] of Object.entries(args)) {
        filter[`args.${argKey}`] = argValue;
      }
    }

    return this.indexer.queryEvents(filter);
  }
}

export { SmartContractQueryAPI, BlockchainIndexer, FeatureFlagService };
